// cakeui-boot: generated by `cakeui new`; `cakeui sync` refreshes it.
//
// This is the only CakeUI-specific module in the frontend. It wires the bridge
// into the app, shows events emitted by Python, and proves the round trip once
// at startup. Delete the import that pulls this in (in your entry file) to detach
// CakeUI entirely: nothing else in the frontend depends on it.
import { invoke, listen, type CakeUIError } from "./cakeui.js";

type ToastPayload = { text: string };

const TOAST_ID = "cakeui-toast";
const TOAST_STYLE = [
  "position:fixed",
  "right:16px",
  "bottom:16px",
  "z-index:2147483647",
  "max-width:min(420px,calc(100vw - 32px))",
  "padding:10px 14px",
  "border-radius:10px",
  "background:rgba(24,24,27,.94)",
  "color:#fafafa",
  "font:13px/1.45 ui-sans-serif,system-ui,sans-serif",
  "box-shadow:0 8px 24px rgba(0,0,0,.28)",
  "opacity:0",
  "transform:translateY(6px)",
  "transition:opacity 140ms ease,transform 140ms ease",
  "pointer-events:none",
  "white-space:pre-wrap",
].join(";");

/** Render a transient message in the corner of the window. */
function showToast(text: string): void {
  let node = document.getElementById(TOAST_ID);
  if (!node) {
    node = document.createElement("div");
    node.id = TOAST_ID;
    node.setAttribute("role", "status");
    node.setAttribute("aria-live", "polite");
    node.style.cssText = TOAST_STYLE;
    document.body.appendChild(node);
  }

  node.textContent = text;
  // Force a style flush so repeated toasts re-animate.
  void node.offsetWidth;
  node.style.opacity = "1";
  node.style.transform = "translateY(0)";

  window.clearTimeout(Number(node.dataset.timer ?? 0));
  const timer = window.setTimeout(() => {
    node.style.opacity = "0";
    node.style.transform = "translateY(6px)";
  }, 2400);
  node.dataset.timer = String(timer);
}

// Python -> JS: anything sent with app.emit("toast", ...) or window.emit(...).
const stopListening = listen<ToastPayload>("toast", ({ text }) => showToast(text));
window.addEventListener("beforeunload", stopListening);

if (!("pywebview" in window)) {
  // Opened in a plain browser (`npm run dev`): the bridge will never appear.
  console.info("[cakeui] No CakeUI window detected. Run `cakeui dev` to talk to Python.");
}

// One round trip at startup: invoke -> Python -> window.emit -> listen above.
void invoke("notify", { text: "CakeUI bridge connected" }).catch((error: unknown) => {
  const { code, message } = error as Partial<CakeUIError>;
  console.error("[cakeui] bridge handshake failed", code ?? "error", message ?? error);
});
